    billing_unknown_count = stats_usage_buckets.billing_unknown_count + excluded.billing_unknown_count,
    label = excluded.label,
    last_used_at = GREATEST(stats_usage_buckets.last_used_at, excluded.last_used_at);
    RETURN NEW;
END $$;


