--
-- Name: stats_usage_attempt_source; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.stats_usage_attempt_source AS
 SELECT 'attempt'::text AS source_kind,
    a.id AS source_id,
    'global'::text AS scope,
    ''::text AS identity,
    ((t.started_at / 900000) * 900000) AS bucket_start,
    NULL::text AS entity_id,
    ''::text AS label,
    0 AS request_count,
    0 AS error_count,
    0 AS terminal_request_count,
    0 AS failed_request_count,
        CASE
            WHEN ((a.status = 'completed'::text) OR ((a.status = 'failed'::text) AND (a.error_source = 'upstream'::text))) THEN 1
            ELSE 0
        END AS upstream_request_count,
        CASE
            WHEN ((a.status = 'failed'::text) AND (a.error_source = 'upstream'::text)) THEN 1
            ELSE 0
        END AS upstream_error_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.input_tokens IS NOT NULL) AND (a.cache_read_tokens IS NOT NULL)) THEN
            CASE
                WHEN (a.input_tokens > a.cache_read_tokens) THEN (a.input_tokens - a.cache_read_tokens)
                ELSE (0)::bigint
            END
            ELSE (0)::bigint
        END AS input_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.input_tokens IS NOT NULL) AND (a.cache_read_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS input_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN a.output_tokens
            ELSE (0)::bigint
        END AS output_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS output_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_read_tokens IS NOT NULL)) THEN a.cache_read_tokens
            ELSE (0)::bigint
        END AS cache_read_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_read_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS cache_read_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_write_tokens IS NOT NULL)) THEN a.cache_write_tokens
            ELSE (0)::bigint
        END AS cache_write_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_write_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS cache_write_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.reasoning_tokens IS NOT NULL)) THEN a.reasoning_tokens
            ELSE (0)::bigint
        END AS reasoning_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.reasoning_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS reasoning_tokens_known,
    0 AS duration_ms_sum,
    0 AS duration_ms_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.first_token_ms, (0)::bigint)
            ELSE (0)::bigint
        END AS first_token_ms_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.first_token_ms IS NOT NULL)) THEN 1
            ELSE 0
        END AS first_token_ms_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN 1
            ELSE 0
        END AS successful_attempt_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS successful_output_known_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.duration_ms IS NOT NULL)) THEN 1
            ELSE 0
        END AS successful_duration_known_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.output_tokens, (0)::bigint)
            ELSE (0)::bigint
        END AS successful_output_sum,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.duration_ms, (0)::bigint)
            ELSE (0)::bigint
        END AS successful_duration_sum,
    t.started_at AS last_used_at,
        CASE
            WHEN (a.cost_custom_nanos IS NOT NULL) THEN a.cost_custom_nanos
            ELSE (0)::bigint
        END AS cost_custom_nanos,
        CASE
            WHEN (a.cost_custom_nanos IS NULL) THEN COALESCE(a.cost_usd_nanos, (0)::bigint)
            ELSE (0)::bigint
        END AS cost_usd_unconverted_nanos,
        CASE
            WHEN (a.cost_usd_nanos IS NOT NULL) THEN 1
            ELSE 0
        END AS cost_known_count,
        CASE
            WHEN ((a.status <> 'running'::text) AND (a.cost_basis IS NOT NULL) AND (a.cost_usd_nanos IS NULL)) THEN 1
            ELSE 0
        END AS cost_unknown_count,
        CASE
            WHEN ((a.cost_basis = 'usage'::text) AND (a.cost_custom_nanos IS NOT NULL)) THEN a.cost_custom_nanos
            ELSE (0)::bigint
        END AS payg_cost_custom_nanos,
        CASE
            WHEN ((a.cost_basis = 'usage'::text) AND (a.cost_custom_nanos IS NULL)) THEN COALESCE(a.cost_usd_nanos, (0)::bigint)
            ELSE (0)::bigint
        END AS payg_cost_usd_unconverted_nanos,
        CASE
            WHEN ((a.cost_basis = 'usage'::text) AND (a.cost_usd_nanos IS NOT NULL)) THEN 1
            ELSE 0
        END AS payg_cost_known_count,
        CASE
            WHEN ((a.status <> 'running'::text) AND (a.cost_basis = 'usage'::text) AND (a.cost_usd_nanos IS NULL)) THEN 1
            ELSE 0
        END AS payg_cost_unknown_count,
        CASE
            WHEN ((a.billing_state = 'charged'::text) AND (a.billing_custom_nanos IS NOT NULL)) THEN a.billing_custom_nanos
            ELSE (0)::bigint
        END AS billing_custom_nanos,
        CASE
            WHEN ((a.billing_state = 'charged'::text) AND (a.billing_custom_nanos IS NULL)) THEN COALESCE(a.billing_usd_nanos, (0)::bigint)
            ELSE (0)::bigint
        END AS billing_usd_unconverted_nanos,
        CASE
            WHEN (a.billing_state = 'charged'::text) THEN 1
            ELSE 0
        END AS billing_charged_count,
        CASE
            WHEN (a.billing_state = 'unknown'::text) THEN 1
            ELSE 0
        END AS billing_unknown_count
   FROM (public.target_attempt_observations a
     JOIN public.model_turn_observations t ON ((t.id = a.model_turn_id)))
UNION ALL
 SELECT 'attempt'::text AS source_kind,
    a.id AS source_id,
    'model'::text AS scope,
    t.route_id AS identity,
    ((t.started_at / 900000) * 900000) AS bucket_start,
    NULLIF(t.route_id, ''::text) AS entity_id,
    COALESCE(NULLIF(t.model_display_name, ''::text), t.route_id) AS label,
    0 AS request_count,
    0 AS error_count,
    0 AS terminal_request_count,
    0 AS failed_request_count,
    0 AS upstream_request_count,
    0 AS upstream_error_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.input_tokens IS NOT NULL) AND (a.cache_read_tokens IS NOT NULL)) THEN
            CASE
                WHEN (a.input_tokens > a.cache_read_tokens) THEN (a.input_tokens - a.cache_read_tokens)
                ELSE (0)::bigint
            END
            ELSE (0)::bigint
        END AS input_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.input_tokens IS NOT NULL) AND (a.cache_read_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS input_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN a.output_tokens
            ELSE (0)::bigint
        END AS output_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS output_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_read_tokens IS NOT NULL)) THEN a.cache_read_tokens
            ELSE (0)::bigint
        END AS cache_read_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_read_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS cache_read_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_write_tokens IS NOT NULL)) THEN a.cache_write_tokens
            ELSE (0)::bigint
        END AS cache_write_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.cache_write_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS cache_write_tokens_known,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.reasoning_tokens IS NOT NULL)) THEN a.reasoning_tokens
            ELSE (0)::bigint
        END AS reasoning_tokens_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.reasoning_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS reasoning_tokens_known,
    0 AS duration_ms_sum,
    0 AS duration_ms_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.first_token_ms, (0)::bigint)
            ELSE (0)::bigint
        END AS first_token_ms_sum,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.first_token_ms IS NOT NULL)) THEN 1
            ELSE 0
        END AS first_token_ms_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN 1
            ELSE 0
        END AS successful_attempt_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.output_tokens IS NOT NULL)) THEN 1
            ELSE 0
        END AS successful_output_known_count,
        CASE
            WHEN ((a.status = 'completed'::text) AND (a.duration_ms IS NOT NULL)) THEN 1
            ELSE 0
        END AS successful_duration_known_count,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.output_tokens, (0)::bigint)
            ELSE (0)::bigint
        END AS successful_output_sum,
        CASE
            WHEN (a.status = 'completed'::text) THEN COALESCE(a.duration_ms, (0)::bigint)
            ELSE (0)::bigint
        END AS successful_duration_sum,
    t.started_at AS last_used_at,
        CASE
            WHEN (a.cost_custom_nanos IS NOT NULL) THEN a.cost_custom_nanos
            ELSE (0)::bigint
        END AS cost_custom_nanos,
        CASE
            WHEN (a.cost_custom_nanos IS NULL) THEN COALESCE(a.cost_usd_nanos, (0)::bigint)
            ELSE (0)::bigint
        END AS cost_usd_unconverted_nanos,
        CASE
            WHEN (a.cost_usd_nanos IS NOT NULL) THEN 1
            ELSE 0
        END AS cost_known_count,
        CASE
            WHEN ((a.status <> 'running'::text) AND (a.cost_basis IS NOT NULL) AND (a.cost_usd_nanos IS NULL)) THEN 1
            ELSE 0
        END AS cost_unknown_count,
        CASE
            WHEN ((a.cost_basis = 'usage'::text) AND (a.cost_custom_nanos IS NOT NULL)) THEN a.cost_custom_nanos
            ELSE (0)::bigint
        END AS payg_cost_custom_nanos,
        CASE
            WHEN ((a.cost_basis = 'usage'::text) AND (a.cost_custom_nanos IS NULL)) THEN COALESCE(a.cost_usd_nanos, (0)::bigint)
            ELSE (0)::bigint
        END AS payg_cost_usd_unconverted_nanos,
        CASE
