    0 AS cache_read_tokens_sum,
    0 AS cache_read_tokens_known,
    0 AS cache_write_tokens_sum,
    0 AS cache_write_tokens_known,
    0 AS reasoning_tokens_sum,
    0 AS reasoning_tokens_known,
    0 AS duration_ms_sum,
    0 AS duration_ms_count,
    0 AS first_token_ms_sum,
    0 AS first_token_ms_count,
    0 AS successful_attempt_count,
    0 AS successful_output_known_count,
    0 AS successful_duration_known_count,
    0 AS successful_output_sum,
    0 AS successful_duration_sum,
    r.started_at AS last_used_at,
    0 AS cost_custom_nanos,
    0 AS cost_usd_unconverted_nanos,
    0 AS cost_known_count,
    0 AS cost_unknown_count,
    0 AS payg_cost_custom_nanos,
    0 AS payg_cost_usd_unconverted_nanos,
    0 AS payg_cost_known_count,
    0 AS payg_cost_unknown_count,
    0 AS billing_custom_nanos,
    0 AS billing_usd_unconverted_nanos,
    0 AS billing_charged_count,
    0 AS billing_unknown_count
   FROM (public.inference_run_observations r
     JOIN ( SELECT target_attempt_observations.run_id,
            target_attempt_observations.provider_id,
            max(target_attempt_observations.provider_name) AS provider_name
           FROM public.target_attempt_observations
          GROUP BY target_attempt_observations.run_id, target_attempt_observations.provider_id) p ON ((p.run_id = r.id)));


--
-- Name: stats_usage_turn_source; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.stats_usage_turn_source AS
 SELECT 'turn'::text AS source_kind,
    t.id AS source_id,
    'global'::text AS scope,
    ''::text AS identity,
    ((t.started_at / 900000) * 900000) AS bucket_start,
    NULL::text AS entity_id,
    ''::text AS label,
    0 AS request_count,
    0 AS error_count,
    0 AS terminal_request_count,
    0 AS failed_request_count,
    0 AS upstream_request_count,
    0 AS upstream_error_count,
    0 AS input_tokens_sum,
    0 AS input_tokens_known,
    0 AS output_tokens_sum,
    0 AS output_tokens_known,
    0 AS cache_read_tokens_sum,
    0 AS cache_read_tokens_known,
    0 AS cache_write_tokens_sum,
    0 AS cache_write_tokens_known,
    0 AS reasoning_tokens_sum,
    0 AS reasoning_tokens_known,
    COALESCE((t.finished_at - t.started_at), (0)::bigint) AS duration_ms_sum,
        CASE
            WHEN (t.finished_at IS NOT NULL) THEN 1
            ELSE 0
        END AS duration_ms_count,
    0 AS first_token_ms_sum,
    0 AS first_token_ms_count,
    0 AS successful_attempt_count,
    0 AS successful_output_known_count,
    0 AS successful_duration_known_count,
    0 AS successful_output_sum,
    0 AS successful_duration_sum,
    t.started_at AS last_used_at,
    0 AS cost_custom_nanos,
    0 AS cost_usd_unconverted_nanos,
    0 AS cost_known_count,
    0 AS cost_unknown_count,
    0 AS payg_cost_custom_nanos,
    0 AS payg_cost_usd_unconverted_nanos,
    0 AS payg_cost_known_count,
    0 AS payg_cost_unknown_count,
    0 AS billing_custom_nanos,
    0 AS billing_usd_unconverted_nanos,
    0 AS billing_charged_count,
    0 AS billing_unknown_count
   FROM public.model_turn_observations t
UNION ALL
 SELECT 'turn'::text AS source_kind,
    t.id AS source_id,
    'model'::text AS scope,
    t.route_id AS identity,
    ((t.started_at / 900000) * 900000) AS bucket_start,
    NULLIF(t.route_id, ''::text) AS entity_id,
    COALESCE(NULLIF(t.model_display_name, ''::text), t.route_id) AS label,
    1 AS request_count,
    0 AS error_count,
    0 AS terminal_request_count,
    0 AS failed_request_count,
    0 AS upstream_request_count,
    0 AS upstream_error_count,
    0 AS input_tokens_sum,
    0 AS input_tokens_known,
    0 AS output_tokens_sum,
    0 AS output_tokens_known,
    0 AS cache_read_tokens_sum,
    0 AS cache_read_tokens_known,
    0 AS cache_write_tokens_sum,
    0 AS cache_write_tokens_known,
    0 AS reasoning_tokens_sum,
    0 AS reasoning_tokens_known,
    COALESCE((t.finished_at - t.started_at), (0)::bigint) AS duration_ms_sum,
        CASE
            WHEN (t.finished_at IS NOT NULL) THEN 1
            ELSE 0
        END AS duration_ms_count,
    0 AS first_token_ms_sum,
    0 AS first_token_ms_count,
    0 AS successful_attempt_count,
    0 AS successful_output_known_count,
    0 AS successful_duration_known_count,
    0 AS successful_output_sum,
    0 AS successful_duration_sum,
    t.started_at AS last_used_at,
    0 AS cost_custom_nanos,
    0 AS cost_usd_unconverted_nanos,
    0 AS cost_known_count,
    0 AS cost_unknown_count,
    0 AS payg_cost_custom_nanos,
    0 AS payg_cost_usd_unconverted_nanos,
    0 AS payg_cost_known_count,
    0 AS payg_cost_unknown_count,
    0 AS billing_custom_nanos,
    0 AS billing_usd_unconverted_nanos,
    0 AS billing_charged_count,
    0 AS billing_unknown_count
   FROM public.model_turn_observations t
UNION ALL
 SELECT 'turn'::text AS source_kind,
    t.id AS source_id,
    'api_key'::text AS scope,
    COALESCE(t.api_key_id, ''::text) AS identity,
    ((t.started_at / 900000) * 900000) AS bucket_start,
    t.api_key_id AS entity_id,
    COALESCE(NULLIF(t.api_key_name, ''::text), t.api_key_id, 'Unknown API Key'::text) AS label,
    1 AS request_count,
    0 AS error_count,
    0 AS terminal_request_count,
    0 AS failed_request_count,
    0 AS upstream_request_count,
    0 AS upstream_error_count,
    0 AS input_tokens_sum,
    0 AS input_tokens_known,
    0 AS output_tokens_sum,
    0 AS output_tokens_known,
    0 AS cache_read_tokens_sum,
    0 AS cache_read_tokens_known,
    0 AS cache_write_tokens_sum,
    0 AS cache_write_tokens_known,
    0 AS reasoning_tokens_sum,
    0 AS reasoning_tokens_known,
    COALESCE((t.finished_at - t.started_at), (0)::bigint) AS duration_ms_sum,
        CASE
            WHEN (t.finished_at IS NOT NULL) THEN 1
            ELSE 0
        END AS duration_ms_count,
    0 AS first_token_ms_sum,
    0 AS first_token_ms_count,
    0 AS successful_attempt_count,
    0 AS successful_output_known_count,
    0 AS successful_duration_known_count,
    0 AS successful_output_sum,
    0 AS successful_duration_sum,
    t.started_at AS last_used_at,
    0 AS cost_custom_nanos,
    0 AS cost_usd_unconverted_nanos,
    0 AS cost_known_count,
    0 AS cost_unknown_count,
    0 AS payg_cost_custom_nanos,
    0 AS payg_cost_usd_unconverted_nanos,
    0 AS payg_cost_known_count,
    0 AS payg_cost_unknown_count,
    0 AS billing_custom_nanos,
    0 AS billing_usd_unconverted_nanos,
    0 AS billing_charged_count,
    0 AS billing_unknown_count
   FROM public.model_turn_observations t;


